// retry.ts
export type RetryOptions = {
  /** Maximum number of attempts (including the first try). */
  maxAttempts: number;
  /** Initial delay in ms before the first retry. */
  baseDelay: number;
  /** Upper bound for the delay in ms. */
  maxDelay: number;
  /** Optional factor to use for exponential growth. */
  exponent?: number;
  /** Optional predicate that decides whether an error is retry‑able. */
  isRetryable?: (err: unknown) => boolean;
  /** AbortSignal to cancel the whole operation. */
  signal?: AbortSignal;
};

export type RetryResult<T> = {
  /** The value returned by the successful attempt. */
  result: T;
  /** Number of attempts that were performed. */
  attempts: number;
};

/**
 * Sleep for `ms` milliseconds.
 */
function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
